@trait Sensor {
  @unknown
  reading: Temperature
  display: other ?? reading
}

@trait Health {
  maxHP: 100
  current: maxHP
  label: describe(maxHP)
}

@trait T {
  x: Bool
  @on_p => { if x { hp = 1 } }
}

@trait T {
  enabled: Bool
  @on_p => { if not enabled { return } }
}

@trait T {
  x: Bool
  @on_p => { emit(changed, { from_state, to_state }) }
}

@trait T {
  x: Bool
  @on_p => { r = compute() ; return r }
}

@trait T {
  x: Bool
  @on_p => { r = analyzer.analyze(composition, file_path) return r }
}

@trait Sensor {
  @unknown
  raw: Temperature
  calibrated: Temperature = raw
}

@trait Sensor {
  @unknown
  raw: Temperature
  calibrated: Temperature = raw ?? 0.0
}

@trait T {
  a: Num
  b: Num
  c: a ?? b ?? 5
}

@trait Health {
  maxHP: 100
  @on_spawn(e) => { hp = maxHP }
  @receipt cfg { type: "HealthReceipt" }
}

struct Point {
  x: i32
  y: i32
}
enum Mode {
  Fast
  Safe
}

struct Sensor {
  @unknown reading: i32
  calibrated: bool
}
function main(): i32 {
  slot sensor: Sensor = Sensor(unknown("underdetermined"), true)
  return load(sensor.reading) ?? 0
}
